  ('6823d93b-6e52-3e9f-a478-cffad446295f'::uuid, 'f9512c15-ec1c-4fcb-a5ec-a2c6ac3a020e'::uuid, 'module', 'speaking-listen-and-repeat', 'speaking-listen-and-repeat', 'Speaking: Listen and Repeat', 'How the seven Listen and Repeat sentences work, how exact repetition is scored, and a practical system of chunking, stress and shadowing to repeat longer sentences accurately and clearly, with original practice sets and drills.', 'published', 'public', 'en', 9, 'Speaking: Listen and Repeat | TOEFL Playbook', 'How the seven Listen and Repeat sentences work, how exact repetition is scored, and a practical system of chunking, stress and shadowing to repeat longer sentences accurately and clearly, with original practice sets and drills.', array['TOEFL', 'TOEFL iBT', 'TOEFL Playbook', 'Listen and Repeat', 'TOEFL speaking', 'repeat sentences', 'TOEFL 2026 speaking']::text[], now(), $tpb${"seeded_by":"20261028100900_toefl_playbook_public_modules","content_revision":"toefl-2026-format-v1","hero_kicker":"Module 9 · Speaking","module_group":"skill_speaking","section":"speaking","word_count":5325,"section_count":29,"reading_time_minutes":27,"practice_url":"https://toefl.schood.online/practice","format_basis":"TOEFL iBT updated 21 January 2026 (ETS overview, 2026 blueprint, April 2026 score-scale report)","last_verified":"2026-10-24","verification_status":"verified","source_file":"content/toefl-playbook/modules/speaking-listen-and-repeat.md"}$tpb$::jsonb),
