  ('149dcab4-9420-7eb3-0049-241d4004967c'::uuid, 'f9512c15-ec1c-4fcb-a5ec-a2c6ac3a020e'::uuid, 'module', 'test-day-guide', 'test-day-guide', 'Test Day Guide: Test Centre and Home Edition', 'A practical test-day protocol for the 2026 TOEFL iBT: the last two weeks, ID and check-in, Home Edition room and equipment rules, behaviours that can invalidate a test, a section-by-section game plan with no breaks, the report-or-cancel decision, and what happens after.', 'published', 'public', 'en', 11, 'Test Day Guide: Test Centre and Home Edition | TOEFL Playbook', 'A practical test-day protocol for the 2026 TOEFL iBT: the last two weeks, ID and check-in, Home Edition room and equipment rules, behaviours that can invalidate a test, a section-by-section game plan with no breaks, the report-or-cancel decision, and what happens after.', array['TOEFL', 'TOEFL iBT', 'TOEFL Playbook', 'TOEFL test day', 'TOEFL Home Edition rules', 'TOEFL test center', 'TOEFL check-in', 'TOEFL report or cancel scores']::text[], now(), $tpb${"seeded_by":"20261028100900_toefl_playbook_public_modules","content_revision":"toefl-2026-format-v1","hero_kicker":"Module 11 · Test day","module_group":"test_day_protocol","section":"all","word_count":4253,"section_count":28,"reading_time_minutes":22,"practice_url":"https://toefl.schood.online/practice","format_basis":"TOEFL iBT updated 21 January 2026 (ETS overview, 2026 blueprint, April 2026 score-scale report)","last_verified":"2026-10-24","verification_status":"verified","source_file":"content/toefl-playbook/modules/test-day-guide.md"}$tpb$::jsonb),
  ('5526cc29-ed95-51ff-3523-15397aa8083d'::uuid, 'f9512c15-ec1c-4fcb-a5ec-a2c6ac3a020e'::uuid, 'module', 'score-goals-and-study-plans', 'score-goals-and-study-plans', 'Score Goals and Study Plans', 'Turn a university requirement, written on the 1-6 scale, the legacy 0-120 scale or as an IELTS equivalent, into section targets, diagnose your starting point, and build a realistic 4, 8 or 12 week TOEFL plan around the Playbook modules.', 'published', 'public', 'en', 12, 'Score Goals and Study Plans | TOEFL Playbook', 'Turn a university requirement, written on the 1-6 scale, the legacy 0-120 scale or as an IELTS equivalent, into section targets, diagnose your starting point, and build a realistic 4, 8 or 12 week TOEFL plan around the Playbook modules.', array['TOEFL', 'TOEFL iBT', 'TOEFL Playbook', 'TOEFL score goals', 'TOEFL study plan', 'TOEFL requirement', 'TOEFL 1-6 target', 'TOEFL 0-120 equivalent']::text[], now(), $tpb${"seeded_by":"20261028100900_toefl_playbook_public_modules","content_revision":"toefl-2026-format-v1","hero_kicker":"Module 12 · Planning","module_group":"result_strategy","section":"all","word_count":4407,"section_count":27,"reading_time_minutes":23,"practice_url":"https://toefl.schood.online/practice","format_basis":"TOEFL iBT updated 21 January 2026 (ETS overview, 2026 blueprint, April 2026 score-scale report)","last_verified":"2026-10-24","verification_status":"verified","source_file":"content/toefl-playbook/modules/score-goals-and-study-plans.md"}$tpb$::jsonb),
  ('2cf0c0ea-9d36-6448-bcdc-ca995f032231'::uuid, 'f9512c15-ec1c-4fcb-a5ec-a2c6ac3a020e'::uuid, 'module', 'retake-and-mybest-strategy', 'retake-and-mybest-strategy', 'Retakes and MyBest Strategy', 'When and how to retake the TOEFL iBT: the official retake rule, how MyBest scores work on the 1–6 scale and across the scale change, who decides whether MyBest counts, diagnosing a shortfall, retake timing, score review versus retaking, sending scores, and retake plans.', 'published', 'public', 'en', 13, 'Retakes and MyBest Strategy | TOEFL Playbook', 'When and how to retake the TOEFL iBT: the official retake rule, how MyBest scores work on the 1–6 scale and across the scale change, who decides whether MyBest counts, diagnosing a shortfall, retake timing, score review versus retaking, sending scores, and retake plans.', array['TOEFL', 'TOEFL iBT', 'TOEFL Playbook', 'TOEFL retake', 'TOEFL MyBest scores', 'TOEFL superscore', 'TOEFL score review', 'TOEFL retake waiting period']::text[], now(), $tpb${"seeded_by":"20261028100900_toefl_playbook_public_modules","content_revision":"toefl-2026-format-v1","hero_kicker":"Module 13 · After your result","module_group":"result_strategy","section":"all","word_count":3993,"section_count":28,"reading_time_minutes":20,"practice_url":"https://toefl.schood.online/practice","format_basis":"TOEFL iBT updated 21 January 2026 (ETS overview, 2026 blueprint, April 2026 score-scale report)","last_verified":"2026-10-24","verification_status":"verified","source_file":"content/toefl-playbook/modules/retake-and-mybest-strategy.md"}$tpb$::jsonb)
